        m_ = n_ * h_ * w_
        z = self._z
        var = self._var
        gamma = self._gamma
        eps = self._eps

        dx = _zeros(self._x_shape)
        dgamma = [0.0] * c_
        dbeta = [0.0] * c_
        for c in range(c_):
            # 第一遍：按 n→h→w 求该通道完整的 dbeta、dgamma
            dg = 0.0
            db = 0.0
            for n in range(n_):
                z_c = z[n][c]
                dy_c = dy[n][c]
                for hh in range(h_):
                    z_row = z_c[hh]
                    dy_row = dy_c[hh]
                    for ww in range(w_):
                        gv = dy_row[ww]
                        db += gv
                        dg += gv * z_row[ww]
            if not (math.isfinite(db) and math.isfinite(dg)):
                raise ValueError("反向计算产生非有限值（NaN/inf）")
            dgamma[c] = dg
            dbeta[c] = db

            # 第二遍：用通道完整总和计算逐元素 dx
            std = math.sqrt(var[c] + eps)
            scale = gamma[c] / std
            if not math.isfinite(scale):
                raise ValueError("反向计算产生非有限值（NaN/inf）")
            for n in range(n_):
                z_c = z[n][c]
                dy_c = dy[n][c]
                dx_c = dx[n][c]
                for hh in range(h_):
                    z_row = z_c[hh]
                    dy_row = dy_c[hh]
                    dx_row = dx_c[hh]
                    for ww in range(w_):
                        val = scale * (dy_row[ww] - (db + z_row[ww] * dg) / m_)
                        if not math.isfinite(val):
                            raise ValueError("反向计算产生非有限值（NaN/inf）")
                        dx_row[ww] = val
        return dx, dgamma, dbeta


def _deep_copy(t):
    """递归复制嵌套 list；标量原样返回。"""
    if isinstance(t, list):
        return [_deep_copy(v) for v in t]
    return t


def _leaf_slots(t):
    """按从外到内的嵌套顺序产出每个标量所在的 (容器, 下标)。"""
    for i in range(len(t)):
        v = t[i]
        if isinstance(v, list):
            for slot in _leaf_slots(v):
                yield slot
        else:
            yield (t, i)


def _flatten_into(t, out):
    """按从外到内的嵌套顺序把全部标量追加到 out。"""
    for v in t:
        if isinstance(v, list):
            _flatten_into(v, out)
        else:
            out.append(v)
